func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddWithZero(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "zero plus zero", a: 0, b: 0, want: 0},
		{name: "zero plus positive", a: 0, b: 7, want: 7},
		{name: "positive plus zero", a: 7, b: 0, want: 7},
		{name: "zero plus negative", a: 0, b: -4, want: -4},
		{name: "negative plus zero", a: -4, b: 0, want: -4},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

